<TimelineKeyframe time={7.5} label="Position keyframe">
  {/* Custom marker shape — defaults to a lime diamond */}
  <div className="w-3 h-3 bg-primary rotate-45" />
</TimelineKeyframe>

function MyZoomControl() {
  const { zoom, setZoom } = useTimeline();

  return (
    <div className="flex gap-1">
      <button onClick={() => setZoom(zoom * 2)}>2×</button>
      <button onClick={() => setZoom(zoom * 0.5)}>0.5×</button>
      <button onClick={() => setZoom(50)}>Reset</button>
    </div>
  );
}

import { useTimeline } from "@/components/bevelui/timeline";

function PlaybackSync() {
  const {
    currentTime,
    duration,
    zoom,
    scrubTo,
    setZoom,
    timeToPixel,
    pixelToTime,
    visibleRange,
  } = useTimeline();

  // Sync with an external audio element
  React.useEffect(() => {
    audioRef.current!.currentTime = currentTime;
  }, [currentTime]);

  // Jump to a specific timecode
  return <button onClick={() => scrubTo(45.3)}>Go to 45.3s</button>;
}
